public enum RoomType { Standard, Deluxe, Suite }

public class Room
{
    public string Number { get; }
    public RoomType Type { get; }
    public decimal PricePerNight { get; }
    public IReadOnlyCollection<string> Amenities { get; }
}

public class Guest
{
    public Guid Id { get; } = Guid.NewGuid();
    public string Name { get; set; }
    public string Email { get; set; }
    public string Phone { get; set; }
}

public class Reservation
{
    public string Id { get; } = Guid.NewGuid().ToString();
    public Room Room { get; }
    public Guest Guest { get; }
    public DateOnly CheckIn { get; }
    public DateOnly CheckOut { get; }
    public decimal Total => (CheckOut.DayNumber - CheckIn.DayNumber) * Room.PricePerNight;

    public bool Overlaps(DateOnly start, DateOnly end)
    {
        return CheckIn < end && CheckOut > start;
    }
}

public class Hotel
{
    private readonly List<Room> _rooms = new();
    private readonly List<Reservation> _reservations = new();

    public IReadOnlyCollection<Room> SearchAvailability(RoomType type, DateOnly from, DateOnly to)
    {
        var bookedRoomNumbers = _reservations
            .Where(r => r.Room.Type == type && r.Overlaps(from, to))
            .Select(r => r.Room.Number)
            .ToHashSet();

        return _rooms
            .Where(r => r.Type == type && !bookedRoomNumbers.Contains(r.Number))
            .ToList();
    }

    public Reservation Book(Room room, Guest guest, DateOnly checkIn, DateOnly checkOut)
    {
        if (SearchAvailability(room.Type, checkIn, checkOut).All(r => r.Number != room.Number))
            throw new InvalidOperationException("Room not available");
        var reservation = new Reservation(room, guest, checkIn, checkOut);
        _reservations.Add(reservation);
        return reservation;
    }
}
